package de.schaepi.puls180;
import android.app.*;import android.content.*;import android.hardware.biometrics.BiometricManager;import android.hardware.biometrics.BiometricPrompt;import android.os.CancellationSignal;import android.text.InputType;import android.util.Base64;import android.widget.*;import java.security.*;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;
public final class AppLock{
 private static boolean skipOnce=false;private static long lastPause=0;private AppLock(){}
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("appLock",0);}
 public static void notePause(){lastPause=android.os.SystemClock.elapsedRealtime();}
 public static boolean ensure(Activity a){long elapsed=lastPause==0?Long.MAX_VALUE:android.os.SystemClock.elapsedRealtime()-lastPause;int mode=prefs(a).getInt("mode",0);long delay=prefs(a).getLong("delay",0);if(mode==0||elapsed<2000||(delay>0&&elapsed<delay))return false;if(skipOnce){skipOnce=false;return false;}if(mode==1)pinUnlock(a);else biometricUnlock(a);return true;}
 public static void configure(Activity a){int mode=prefs(a).getInt("mode",0);new AlertDialog.Builder(a).setTitle("App-Sperre").setSingleChoiceItems(new String[]{"Aus","PIN","Biometrie oder Geräte-PIN"},mode,(d,w)->{d.dismiss();if(w==0){prefs(a).edit().clear().apply();Toast.makeText(a,"App-Sperre ausgeschaltet",0).show();}else if(w==1)setPin(a);else enableBiometric(a);}).setNegativeButton("Abbrechen",null).show();}
 private static EditText field(Context c,String hint){EditText e=new EditText(c);e.setHint(hint);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8)});return e;}
 private static void setPin(Activity a){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(30,12,30,8);EditText one=field(a,"PIN (4 bis 8 Ziffern)"),two=field(a,"PIN wiederholen");box.addView(one);box.addView(two);AlertDialog dlg=new AlertDialog.Builder(a).setTitle("App-PIN festlegen").setView(box).setNegativeButton("Abbrechen",null).setPositiveButton("Speichern",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(x->{String p=one.getText().toString(),q=two.getText().toString();if(!p.matches("[0-9]{4,8}")||!p.equals(q)){Toast.makeText(a,"PIN muss 4 bis 8 Ziffern haben; beide Eingaben müssen gleich sein.",1).show();return;}try{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);prefs(a).edit().putInt("mode",1).putString("salt",Base64.encodeToString(salt,Base64.NO_WRAP)).putString("hash",hash(p,salt)).apply();dlg.dismiss();chooseDelay(a,"PIN-Sperre");}catch(Exception e){Toast.makeText(a,"PIN konnte nicht gespeichert werden.",1).show();}}));dlg.show();}
 private static String hash(String pin,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(pin.toCharArray(),salt,120000,256);byte[] out=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();spec.clearPassword();return Base64.encodeToString(out,Base64.NO_WRAP);}
 private static boolean valid(Context c,String pin){try{byte[] salt=Base64.decode(prefs(c).getString("salt",""),Base64.NO_WRAP);return MessageDigest.isEqual(hash(pin,salt).getBytes(java.nio.charset.StandardCharsets.US_ASCII),prefs(c).getString("hash","x").getBytes(java.nio.charset.StandardCharsets.US_ASCII));}catch(Exception e){return false;}}
 private static void pinUnlock(Activity a){EditText pin=field(a,"PIN");AlertDialog dlg=new AlertDialog.Builder(a).setTitle("App gesperrt").setView(pin).setCancelable(false).setNegativeButton("App schließen",(d,w)->a.finishAndRemoveTask()).setPositiveButton("Entsperren",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(x->{if(valid(a,pin.getText().toString())){skipOnce=true;dlg.dismiss();a.recreate();}else{pin.setText("");Toast.makeText(a,"PIN falsch",0).show();}}));dlg.show();}
 private static void chooseDelay(Activity a,String label){new AlertDialog.Builder(a).setTitle("Wann automatisch sperren?").setItems(new String[]{"Sofort beim erneuten Öffnen","Nach 5 Minuten","Nach 15 Minuten"},(d,w)->{long delay=w==1?300000L:w==2?900000L:0L;prefs(a).edit().putLong("delay",delay).apply();Toast.makeText(a,label+" eingeschaltet · "+(w==1?"5 Minuten":w==2?"15 Minuten":"sofort"),0).show();}).setCancelable(false).show();}
 private static int auth(){return BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL;}
 private static void enableBiometric(Activity a){BiometricManager m=a.getSystemService(BiometricManager.class);int available=m==null?BiometricManager.BIOMETRIC_ERROR_HW_UNAVAILABLE:(android.os.Build.VERSION.SDK_INT>=30?m.canAuthenticate(auth()):m.canAuthenticate());if(available!=BiometricManager.BIOMETRIC_SUCCESS){Toast.makeText(a,"Bitte zuerst Fingerabdruck, Gesicht oder Geräte-PIN in Android einrichten.",1).show();return;}prefs(a).edit().clear().putInt("mode",2).apply();chooseDelay(a,"Biometrische App-Sperre");}
 private static void biometricUnlock(Activity a){try{(android.os.Build.VERSION.SDK_INT>=30?new BiometricPrompt.Builder(a).setTitle("Puls 180 entsperren").setSubtitle("Fingerabdruck, Gesicht oder Geräte-PIN verwenden").setAllowedAuthenticators(auth()).build():new BiometricPrompt.Builder(a).setTitle("Puls 180 entsperren").setSubtitle("Fingerabdruck oder Geräte-PIN verwenden").setDeviceCredentialAllowed(true).build()).authenticate(new CancellationSignal(),a.getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){skipOnce=true;a.recreate();}@Override public void onAuthenticationError(int code,CharSequence msg){Toast.makeText(a,"Entsperrung beendet: "+msg,Toast.LENGTH_LONG).show();a.finishAndRemoveTask();}});}catch(Exception e){Toast.makeText(a,"Biometrische Entsperrung nicht verfügbar.",1).show();a.finishAndRemoveTask();}}
}







